import React from 'react';
import { Composition, Still, staticFile } from 'remotion';

import { Thumbnail } from './Thumbnail';
import { framesFor, type Manifest, SecretsApi } from './Video';

const FPS = 30;

const cut = ( id: string, name: string ) => (
	<Composition
		id={ id }
		component={ SecretsApi }
		width={ 1920 }
		height={ 1080 }
		fps={ FPS }
		durationInFrames={ FPS * 10 }
		defaultProps={ { manifest: { source: 'scratch', scenes: [] } as Manifest, cut: name } }
		calculateMetadata={ async () => {
			// Generated by `npm run narrate:<cut>`; scene lengths follow the voiceover.
			const manifest: Manifest = await fetch( staticFile( `audio/${ name }/manifest.json` ) ).then( r => r.json() );
			const durationInFrames = manifest.scenes.reduce( ( sum, s ) => sum + framesFor( s.seconds, FPS ), 0 );
			return { durationInFrames, props: { manifest, cut: name } };
		} }
	/>
);

export const RemotionRoot: React.FC = () => (
	<>
		{ cut( 'SecretsApiLinkedin', 'linkedin' ) }
		{ cut( 'SecretsApiDev', 'dev' ) }
		<Still id="Thumbnail" component={ Thumbnail } width={ 1920 } height={ 1080 } />
	</>
);
